def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Check prefix differences
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found first difference
            # Check if we're inserting or replacing
            if len(s_in) == len(s_out):
                return (s_in[i], s_out[i], i)
            elif len(s_in) < len(s_out):
                # Insertion - pattern is empty, replacement is the new char
                return ("", s_out[i], i)
            else:
                # Deletion - pattern is the removed char, replacement is empty
                return (s_in[i], "", i)

    # If we get here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Insertion at end
        return ("", s_out[len(s_in)], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion at end
        return (s_in[len(s_out)], "", len(s_out))
    else:
        return ("", "", -1)  # No difference

